import java.util.Objects;

public class Product {
    // 1. Immutable business key
    private final String sku;
    private String name;
    private String category;
    private double price;

    public Product(String sku, String name, String category, double price) {
        if (sku == null || sku.trim().isEmpty()) throw new IllegalArgumentException("SKU required.");
        this.sku = sku.trim();
        this.name = name;
        this.category = category;
        this.price = price;
    }

    // 2. Canonical 4-step equals recipe
    @Override
    public boolean equals(Object o) {
        if (this == o) return true; // Step 1: Reference identity check
        if (o == null || getClass() != o.getClass()) return false; // Step 2: Null & type check
        Product product = (Product) o; // Step 3: Safe cast
        return Objects.equals(sku, product.sku); // Step 4: Compare key fields
    }

    // 3. Synchronized hashCode
    @Override
    public int hashCode() {
        return Objects.hash(sku);
    }

    // 4. Diagnostic toString
    @Override
    public String toString() {
        return String.format("Product[sku='%s', name='%s', price=$%.2f]", sku, name, price);
    }

    public String getSku() { return sku; }
    public String getName() { return name; }
    public double getPrice() { return price; }
}

class Customer {
    private final String customerId;
    private final String email;
    private String fullName;

    public Customer(String customerId, String email, String fullName) {
        this.customerId = customerId;
        this.email = (email != null) ? email.toLowerCase() : "";
        this.fullName = fullName;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Customer customer = (Customer) o;
        return Objects.equals(customerId, customer.customerId) &&
               Objects.equals(email, customer.email);
    }

    @Override
    public int hashCode() {
        return Objects.hash(customerId, email);
    }

    @Override
    public String toString() {
        return String.format("Customer[id='%s', email='%s', name='%s']", customerId, email, fullName);
    }
}

